import{_ as i,c as t,o as r,ag as a}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Series Packet","description":"","frontmatter":{"title":"Series Packet"},"headers":[],"relativePath":"general/series-packet.md","filePath":"general/series-packet.md","lastUpdated":null}'),l={name:"general/series-packet.md"};function o(s,e,n,c,p,u){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="series-packet" tabindex="-1">Series Packet <a class="header-anchor" href="#series-packet" aria-label="Permalink to &quot;Series Packet&quot;">​</a></h1><h2 id="enclosure-3-review-workflow" tabindex="-1">Enclosure 3 Review Workflow <a class="header-anchor" href="#enclosure-3-review-workflow" aria-label="Permalink to &quot;Enclosure 3 Review Workflow&quot;">​</a></h2><p><strong>Purpose</strong>: To reduce variance, improve efficiency, expand continuity and interoperability, increase transparency, and allow for systemic adjustments to the review.</p><h3 id="broad-steps" tabindex="-1">Broad Steps <a class="header-anchor" href="#broad-steps" aria-label="Permalink to &quot;Broad Steps&quot;">​</a></h3><ul><li><p>Ensure the Task is in the OPCEN RFS Tracker.</p></li><li><p>Upload Enclosure to SIPR Portal.</p><ul><li>Name file: <em>SERIES NAME_ENC 3_Date_Changes (EX. SERIES NAME_ENC 3_202406_Changes)</em>.</li></ul></li><li><p>Review past guidance.</p></li><li><p>Contact with Team (Initial).</p></li><li><p>Read Enclosure.</p></li><li><p>Review and validate with documented changes:</p><ul><li>Ensure MO, SMO, DB, and admin data are identical across enclosures.</li><li>Confirm that Refined Assessment Criteria are a logical derivative of Initial Assessment Criteria.</li><li>Look for proof of research or verification if a dollar amount or cost is provided.</li></ul></li><li><p>Contact with Team as needed with RFIs.</p></li><li><p>Confirm Formatting.</p></li><li><p>Apply corrections.</p></li><li><p>Submit for review:</p><ul><li>OPCEN Leadership.</li><li>Company Leadership.</li></ul></li><li><p>Leadership will return to the team if needed (ENC 3 may not require a return to the team; bring in the team on substantial changes).</p></li></ul><h3 id="steps-taken-for-enclosure-3-review" tabindex="-1">Steps Taken for Enclosure 3 Review <a class="header-anchor" href="#steps-taken-for-enclosure-3-review" aria-label="Permalink to &quot;Steps Taken for Enclosure 3 Review&quot;">​</a></h3><ul><li><p><strong>Ensure that task is in the RFS Tracker</strong>: <a href="https://socom.sharepoint-mil.us/:l:/s/usasoc-1sfc-4pog-1bn-c/FKFS5PZyXDlAqKWw8vtI16MB8QlVLYOcNUeHJVbj2U27eg?e=Thht51" target="_blank" rel="noreferrer">OPCEN RFS</a>.</p><ul><li>If the task is not in the RFS Tracker, add it and appropriately include the requester&#39;s email and team.</li><li>When it is on the RFS tracker, assign yourself and change the status of the RFS to &quot;IN PROGRESS&quot; as you work on it.</li></ul></li><li><p>Upload Enclosure to SIPR Portal.</p><ul><li>Create a folder in the Country Directory: <ul><li>Directory should be: In Development-COUNTRY-SERIES-01. Series Enclosures-03. Enclosure 3.</li></ul></li><li>Name file: <em>SERIES NAME_ENC 3_Date_Changes (EX. SERIES NAME_ENC 3_202406_Changes)</em>.</li><li>Add link to working directory in country chatsurfer (SIPR).</li><li>Leave the original copy in the appropriate enclosure folder and create a &quot;changes&quot; version in the working folder.</li></ul></li><li><p><strong>Review past guidance</strong> from the J39 about Enclosure 3.</p><ul><li>Review PSYOP Kneeboard <strong>[Series Overview]</strong>: (SIPR): <code>https://YOURTSOC.smil.mil/sites/Ops/JED/J39/Kneeboards/</code><ul><li>Find the most current.</li><li>Review the intent of series groups.</li></ul></li><li>Review Objectives and Effects (SIPR): <code>https://YOURTSOC.smil.mil/sites/j5/SOFAssessments/</code></li><li>Ensure portion markings are not overclassified or missing.</li></ul></li><li><p><strong>Contact team for initial comms</strong>.</p><ul><li>Send Email to PSY-T, CC PSY-D Leadership, and FUOPS Leadership.</li><li>The goal is to set up a communication channel for future discussion and to clarify who is working on the RFS and who is the customer of the RFS.</li></ul></li><li><p><strong>Read</strong> the entire Enclosure 3.</p><ul><li>Ensure ENC 3 information still matches ENC 1 and 2.</li><li>Review header slide for correct series name and team information.</li></ul></li></ul><p>[Up] [Required]</p>',8)])])}const m=i(l,[["render",o]]);export{h as __pageData,m as default};
